css:
.cs-qnl-button {
  position: fixed;
  bottom: 20px;
  left: 20px;
  z-index: 1100;
  background: linear-gradient(135deg, #f97316, #ef4444);
  color: white;
  border: none;
  border-radius: 12px;
  padding: 10px 14px;
  font-weight: 800;
  box-shadow: 0 10px 30px rgba(239, 68, 68, 0.35);
  cursor: pointer;
}
.cs-qnl-panel {
  position: fixed;
  bottom: 20px;
  left: 20px;
  width: min(360px, 90vw);
  background: #0f172a;
  color: #e2e8f0;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  padding: 14px;
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.4);
  transform: translateY(140%);
  transition: transform 140ms ease, opacity 140ms ease;
  opacity: 0;
  z-index: 1099;
}
.cs-qnl-panel[data-open="true"] {
  transform: translateY(0);
  opacity: 1;
}
.cs-qnl-panel h3 {
  margin: 0 0 8px 0;
}
.cs-qnl-panel textarea {
  width: 100%;
  min-height: 90px;
  border-radius: 10px;
  padding: 8px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.04);
  color: white;
}
.cs-qnl-panel input[type="text"] {
  width: 100%;
  border-radius: 10px;
  padding: 8px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.04);
  color: white;
}
.cs-qnl-priority {
  display: flex;
  gap: 8px;
  margin: 8px 0;
}
.cs-qnl-pill {
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  cursor: pointer;
  font-weight: 700;
  background: rgba(255, 255, 255, 0.04);
}
.cs-qnl-pill[data-active="true"] {
  background: rgba(249, 115, 22, 0.25);
  border-color: rgba(249, 115, 22, 0.6);
}
.cs-qnl-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 10px;
}

js:
(function() {
  'use strict';
  if (window.__CS_QUICK_NOTE_LAUNCHER__) return;
  window.__CS_QUICK_NOTE_LAUNCHER__ = true;

  const api = window.CardSpoke?.utils;
  let panel;
  let textarea;
  let tagsInput;
  let priority = 'Normal';

  const setPriority = (value) => {
    priority = value;
    document.querySelectorAll('.cs-qnl-pill').forEach((pill) => {
      pill.dataset.active = (pill.dataset.value === value).toString();
    });
  };

  const togglePanel = () => {
    const next = panel.dataset.open !== 'true';
    panel.dataset.open = next.toString();
  };

  const createUI = () => {
    let button = document.querySelector('.cs-qnl-button');
    if (!button) {
      button = document.createElement('button');
      button.className = 'cs-qnl-button';
      button.textContent = 'Quick Note';
      button.title = 'Shift + N';
      button.addEventListener('click', togglePanel);
      document.body.appendChild(button);
    }

    panel = document.querySelector('.cs-qnl-panel');
    if (!panel) {
      panel = document.createElement('div');
      panel.className = 'cs-qnl-panel';
      panel.innerHTML = `
        <h3>Capture note</h3>
        <textarea placeholder="Write the idea..."></textarea>
        <input type="text" class="cs-qnl-tags" placeholder="Tags (comma separated)" />
        <div class="cs-qnl-priority">
          <div class="cs-qnl-pill" data-value="Now">Now</div>
          <div class="cs-qnl-pill" data-value="Next">Next</div>
          <div class="cs-qnl-pill" data-value="Later">Later</div>
          <div class="cs-qnl-pill" data-value="Normal" data-active="true">Normal</div>
        </div>
        <div class="cs-qnl-actions">
          <small>Auto-tags: idea, inbox</small>
          <button class="cs-qnl-button-save">Save</button>
        </div>
      `;
      document.body.appendChild(panel);

      textarea = panel.querySelector('textarea');
      tagsInput = panel.querySelector('.cs-qnl-tags');

      panel.querySelectorAll('.cs-qnl-pill').forEach((pill) => {
        pill.addEventListener('click', () => setPriority(pill.dataset.value));
      });

      panel.querySelector('.cs-qnl-button-save').addEventListener('click', async () => {
        const title = (textarea.value || '').split('
')[0].slice(0, 120) || 'Untitled idea';
        const tags = ['idea', 'inbox'].concat((tagsInput.value || '').split(',').map((t) => t.trim()).filter(Boolean));
        try {
          await api?.createCard?.({ title: `${title} [${priority}]`, body: textarea.value, tags });
          api?.showToast?.('Quick note saved', 'success');
          textarea.value = '';
          tagsInput.value = '';
          setPriority('Normal');
          panel.dataset.open = 'false';
        } catch (e) {
          console.error(e);
          api?.showToast?.('Could not save quick note', 'error');
        }
      });
    }
  };

  const enable = () => {
    createUI();
    document.addEventListener('keydown', (e) => {
      if (e.shiftKey && e.key.toLowerCase() === 'n') togglePanel();
    });
  };

  if (window.CardSpoke_MODS?.register) {
    CardSpoke_MODS.register('plugin-quick-note-launcher', {
      meta: { name: 'Quick Note Launcher', type: 'Plugin', version: '1.0.0' },
      onAppInit: enable,
      onDisable() { document.querySelectorAll('.cs-qnl-panel, .cs-qnl-button').forEach((el) => el.remove()); }
    });
  } else {
    enable();
  }
})();
